/* MariaDB connection and schema (SOW §5-6; docs/STORE-001-design.md).
 *
 * The database runs locally in Docker (docker/compose.yml), listens on
 * 127.0.0.1 only, and uses credentials generated by tools/services.sh. All
 * statements with author data go through prepared statements (no string
 * building), and every change is one transaction.
 */
#ifndef SCRIBODO_DB_H
#define SCRIBODO_DB_H

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

typedef struct {
    char host[64];
    unsigned port;
    char user[64];
    char password[160];
    char database[64];
    unsigned timeout_s; /* connect/read/write timeouts */
} DbConfig;

typedef struct Db Db;

/* Defaults: 127.0.0.1:33061, user/database "scribodo", password from
 * ~/Library/Application Support/Scribodo/services/db_password (or
 * $SCRIBODO_SECRETS). False if the password can't be read. */
bool db_config_default(DbConfig *c, char *err, size_t errlen);

Db *db_open(const DbConfig *c, char *err, size_t errlen);
void db_close(Db *db);
/* Apply any migrations not yet applied (each in its own transaction). */
bool db_migrate(Db *db, char *err, size_t errlen);
/* Tests: apply migrations only up to version `upto`. */
bool db_migrate_upto(Db *db, int upto, char *err, size_t errlen);
int db_schema_version(Db *db);

bool db_begin(Db *db);
bool db_commit(Db *db);
void db_rollback(Db *db);
const char *db_error(Db *db);
/* The connection was lost (the caller should drop it and reconnect). */
bool db_broken(Db *db);
/* Inside db_begin .. commit/rollback (callers that group statements join
 * the caller's transaction instead of starting their own). */
bool db_in_transaction(Db *db);

/* ---- prepared statements ------------------------------------------------- */

/* Parameters: 's' string (const char *, may be NULL), 'i' int64 (int64_t),
 * 'd' double. One letter per '?' in the SQL, e.g. "ssi". */
typedef struct {
    char type;
    const char *s;
    int64_t i;
    double d;
} DbArg;

#define DB_S(v) ((DbArg){ 's', (v), 0, 0 })
#define DB_I(v) ((DbArg){ 'i', NULL, (int64_t)(v), 0 })
#define DB_D(v) ((DbArg){ 'd', NULL, 0, (v) })

/* Run a statement; *affected gets the rows changed (may be NULL). */
bool db_run(Db *db, const char *sql, const DbArg *args, size_t nargs, uint64_t *affected);

/* Query: every row's columns as strings (NULL for SQL NULL). Free with
 * db_rows_free. */
typedef struct {
    size_t nrows, ncols;
    char **cells; /* nrows * ncols */
} DbRows;

bool db_query(Db *db, const char *sql, const DbArg *args, size_t nargs, DbRows *out);
void db_rows_free(DbRows *r);
static inline const char *db_cell(const DbRows *r, size_t row, size_t col) { return r->cells[row * r->ncols + col]; }

/* Checked result decoding. `db_cell_nullable` distinguishes a valid SQL NULL
 * (true with *out == NULL) from a malformed row/column access (false). Numeric
 * readers reject NULL, overflow, non-finite values and trailing bytes. */
bool db_rows_has_columns(const DbRows *r, size_t expected);
bool db_cell_nullable(const DbRows *r, size_t row, size_t col, const char **out);
bool db_cell_text(const DbRows *r, size_t row, size_t col, const char **out);
bool db_cell_i64(const DbRows *r, size_t row, size_t col, int64_t *out);
bool db_cell_u64(const DbRows *r, size_t row, size_t col, uint64_t *out);
bool db_cell_double(const DbRows *r, size_t row, size_t col, double *out);

#endif
